    "lifeStory": "弘忍大师，蕲州黄梅人，俗姓周。相传其前身为破头山栽松道人，受四祖道信记莂而再来，故有“栽松行者”之称。七岁随道信出家，性木讷沉厚，同学戏弄，默然不答；执役舂米，昼则混迹驱使，夜则坐摄至晓，三十年不离师侧，得受衣法，是为禅宗五祖。\n\n道信示寂后，弘忍于黄梅东山（冯茂山）弘化，门下徒众七百余人，龙象辈出，时称“东山法门”。大师接人不论根器，唯以“守本真心”为教：但于行住坐卧中，恒守真心，妄念不生，我所心灭，自然与佛无别。上元年间，岭南樵夫卢惠能负米来山求作佛，弘忍令入碓坊踏碓八月有余。后因传法之事，令门人各呈心偈：上座神秀书“身是菩提树，心如明镜台，时时勤拂拭，勿使惹尘埃”于廊壁；惠能则请人代书“菩提本无树，明镜亦非台，本来无一物，何处惹尘埃”。弘忍知惠能已悟，夜半召其入室，亲讲《金刚经》至“应无所住而生其心”，惠能言下大悟，遂传衣钵，令其南遁。咸亨五年（674年）大师示寂，唐代宗谥“大满禅师”，塔曰“法雨”。其门下分化南北二宗，禅宗自此花开五叶，遍于天下。",
