    "name": "宝志禅师",
    "title": "志公禅师 / 梁代国师",
    "era": "南北朝 (418 - 514)",
    "lifeStory": "宝志禅师（志公大士），南朝宋、齐、梁代高僧，梁武帝尊为国师。世传为观音菩萨化身，性格旷达，言词俚俗而机锋极其犀利。所作《大乘赞》《十四科颂》《十二时颂》《万空歌》风行禅林。志公斥死坐枯禅者“莫作长坐痴人，泥土如何有道”，痛陈“不解即心即佛，真似骑驴觅驴”，为后世世俗破执、直指心性开辟了广阔先河。",
    "teachings": "大道常在目前，莫除声色言语；即心即佛，切忌向外求他。",
