    "lifeStory": "富楼那，全称富楼那弥多罗尼子，意为\u201c满慈子\u201d。迦毗罗卫国（今尼泊尔）人，为佛陀十大弟子之一，以\u201c说法第一\u201d著称。师善说法要，辩才无碍，能以种种譬喻善巧方便令闻者悟道。后往西方输卢那国弘法，于彼建立僧团，自任上座，终于彼国入灭。在《楞严经》中，富楼那问佛陀\u201c清净本然，云何忽生山河大地\u201d——此问直探宇宙缘起之根源，佛陀因此广说三如来藏、四大的本来面目，为《楞严经》核心教义之关键发起。",
