    "teachings": "玄沙宗风以\u201c三种病\u201d为施设：一者不了根身，二者不了境缘，三者不了心体。明示学人修行中易犯之微细执着，层层拨开，令其直见本来。其教绵密细致，与雪峰之高峻形成互补。",
