    "lifeStory": "元来禅师，庐陵（今江西吉安）人，俗姓沙。少出家，后参无明慧经，于慧经座下开悟。师住博山（今江西广丰），大弘曹洞宗风。着《博山参禅警语》一卷，以\u201c参禅念佛等法门，毕竟是生灭心行\u201d为警策，痛陈参禅中之微细弊病，为后世禅修之重要指南。师之教以\u201c警策\u201d为特色——不尚玄妙，唯以切直之言警醒学人，令其于修行中不落诸病。",
