    "lifeStory": "普明禅师，生平不详，以\u201c十牛图颂\u201d闻名禅史。普明所作十牛图，以牧牛喻修心，分十阶段：未牧、初调、受制、回首、驯伏、无碍、任运、相忘、独照、双泯。每图配一颂，将禅宗修行次第以牧牛意象生动呈现。此图后经廓庵师远改编为另一版本（寻牛至入廛垂手），然普明原作亦流传甚广，两者各擅胜场。",
    "teachings": "普明十牛图以牛喻心，以牧童喻修行者：未牧即全迷，初调即始修，受制即摄心，回首即返照，驯伏即调柔，无碍即自在，任运即无功用力，相忘即能所双泯，独照即寂而常照，双泯即理事俱寂。十图层层递进，将禅宗修行次第圆满呈现。",
    "quotes": [
      "未牧：狰狞头角自咆哮，奔走溪山路转遥。",
      "双泯：人牛不见杳无踪，明月光寒万象空。"
    ],
