    "summary": "只管打坐，曹洞宗核心禅法，由宏智正觉系统化、道元禅师极致化。所谓\u201c只管\u201d者，不参话头、不看公案、不求悟、不厌迷——唯默默坐禅而已。身心脱落，脱落身心——坐禅本身即是证悟，非因坐禅而得证悟。此法承曹洞宗\u201c本证妙修\u201d之旨：修行即证悟，证悟即修行，修证一等。道元禅师入宋参天童如净，归日本后着《普劝坐禅仪》，以\u201c不思量、不分判、不造作\u201d为坐禅纲要，将此法发扬光大。",
