    "summary": "保任，即悟后之保护任运。禅宗以为，悟道非终点，乃起点——悟后仍须保任，令悟境不退，习气渐除。如初生婴儿，虽具人身，仍须乳哺养育方能长大；初悟之人，虽见自性，仍须保任磨炼方能成熟。六祖云：\u201c迷时师度，悟了自度。\u201d——悟后之保任，须自度自修。保者，保护悟境不令退失；任者，任运自然不假造作。保中有任，任中有保——非死守悟境，亦非放纵习气。",
