    "summary": "机锋，宗师接引学人之峻烈方便。机者，学人之根机；锋者，宗师之言锋。宗师观学人根机，以一言半句——或问或答、或棒或喝——如刀锋般截断学人意识流，令其于思量不及处亲见本来。机锋之要在于\u201c快\u201d——不容拟议，一拟议即落第二义。如僧问赵州：\u201c如何是祖师西来意？\u201d州曰：\u201c庭前柏树子。\u201d——此即机锋之典型：不以道理答，而以一句截断学人思量。",
