    "context": "六祖惠能得法后，隐于四会猎人队十五年。后至广州法性寺，值印宗法师讲《涅槃经》。时有风吹幡动，一僧曰风动，一僧曰幡动，议论不已，各不相下。惠能进曰：“不是风动，不是幡动，仁者心动。”一众骇然。印宗知是肉身菩萨，延入室内，问：“行者定非常人，久闻黄梅衣法南来，莫是行者否？”惠能曰：“不敢。”于是印宗为惠能剃度，请说东山法门，惠能自此正式出世说法，大阐顿教。",
    "interpretation": "风动、幡动，本是世间现量；二僧争执，却成了情识上的葛藤。惠能一语“仁者心动”，不是抹杀风幡，而是直指争端的根源——见有风幡可争，正是心随境转处。万法唯心所现：心若不动，风幡各住本位，何争之有？此即“三界唯心，万法唯识”的活注脚。后来学者莫错会：不是风幡不曾动，也不是要人如木石般不见风幡；只是于见闻觉知中不被境转，则山河大地尽是真心妙用。二祖所谓“是心是佛”，六祖此语正与相发明。",
    "master": "六祖惠能",
    "source": "六祖坛经 · 行由品",
