    "id": "koan-19",
    "question": "应无所住而生其心",
    "answer": "何期自性本自清净！何期自性本不生灭！何期自性本自具足！何期自性本无动摇！何期自性能生万法！",
    "context": "六祖惠能早年在新州采柴，卖于市市，闻客诵《金刚经》至“应无所住而生其心”，心即开悟。遂往黄梅参五祖弘忍。弘忍命其于碓房破柴踏碓八余月。后五祖夜半召惠能入室，以袈裟遮围，为说《金刚经》，至“应无所住而生其心”，惠能言下大彻大悟，遂唱五句“何期自性”，五祖便传衣钵为第六代祖。",
