    "answer": "默然无言，是真入不二法门！结习未尽，故花粘身；结习尽者，花不附着。",
    "context": "文殊菩萨问维摩诘长者：“何等是菩萨入不二法门？”维摩诘长者默然无言！文殊菩萨赞叹曰：“善哉！善哉！乃至无有文字言语，是真入不二法门！”丈室内天女天花散下，花至菩萨身上纷纷坠落，至舍利子身上紧黏不去。舍利子用神通去花不能。天女笑曰：“结习未尽，故花粘身！若无分别执着，花自坠落。",
