    "interpretation": "\u201c尽大地撮来如粟米大\u201d——将整个大千世界撮成一粒粟米，此乃\u201c一即一切\u201d之华严境界。然\u201c抛向什么处\u201d——此一粒粟米（即一心）抛向何处？雪峰答\u201c抛向漆桶里\u201d——漆桶者，黑暗无光之处，喻无明烦恼。意谓：一粒粟米（清净心）不须抛向别处，即抛向无明烦恼中——烦恼即菩提，生死即涅槃。不须离烦恼求菩提，即烦恼便是菩提。",
