    "answer": "出门便是草。",
    "context": "僧问赵州从谂禅师：\u201c如何是道？\u201d师曰：\u201c出门便是草。\u201d",
    "interpretation": "赵州之\u201c出门便是草\u201d——\u201c门\u201d者，本心之门；\u201c草\u201d者，妄念之草。道不在门外——一出心门，便是妄念丛生。赵州之意：道在门内（本心），不在门外（向外求）。学人向外求道，如出门寻草——越求越远。只须回归本心，不出此门，即见道之本体。",
