    "question": "如何是祖师西来意？",
    "answer": "井底泥牛吼，窗间木马嘶。",
    "context": "僧问石霜庆诸禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c井底泥牛吼，窗间木马嘶。\u201d",
    "interpretation": "石霜以\u201c井底泥牛吼，窗间木马嘶\u201d答\u201c西来意\u201d——泥牛不能吼，木马不能嘶，此乃不可能之事。石霜之意：祖师西来意不可以言语说、不可以思量得——如泥牛吼、木马嘶，非世间事。学人若以言语思量求祖师意，如求泥牛之吼、木马之嘶——终不可得。唯超越言语思量，方能亲见。",
