    "question": "如何是祖师西来意？",
    "answer": "待汝一口吸尽西江水，即向汝道。",
    "context": "僧问马祖道一禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c待汝一口吸尽西江水，即向汝道。\u201d",
