    "interpretation": "赵州以\u201c砖瓦将来\u201d答\u201c西来意\u201d——砖瓦者，最平常之物。学人问祖师西来意，心中必有玄妙之期待；赵州以最平常之砖瓦答之，令其玄妙期待顿破。祖师西来意不在玄妙处，即此砖瓦之平常。僧人追问\u201c岂不是物\u201d——已落分别；赵州答\u201c物即砖瓦\u201d——即物而真，不离物别求道。",
