    "question": "如何是祖师西来意？",
    "answer": "百草头上祖师意。",
    "context": "僧问长沙景岑禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c百草头上祖师意。\u201d",
    "interpretation": "长沙之\u201c百草头上祖师意\u201d——百草者，一切草木；头上者，当下。祖师西来意不在别处，即此百草之当下。百草头上，祖师意——一切草木之生发，皆祖师西来意之显现。如春来草自青——草青即祖师意，不须别求。悟自性者，于百草中见祖师意——即事而真，即相而道。",
