    "interpretation": "赵州之\u201c不生不灭\u201d——涅槃者，不生不灭之境界。学人追问\u201c如何是不生不灭\u201d，赵州答\u201c汝今在生灭中\u201d——你现在正在生灭中。意谓：你问不生不灭，你当下之念正是生灭——念念生灭，即是生灭。然生灭之体即不生不灭——如波生灭，水体不生不灭。赵州示学人：不须离生灭别求不生不灭——即此生灭之体即是不生不灭。",
    "master": "赵州从谂",
