    "interpretation": "大珠之\u201c自性是\u201d——善知识者，自性。学人以为善知识在外——须参访名师。大珠直指自性——自性即善知识。六祖云：\u201c自性具三宝\u201d——自性即佛、法、僧。自性本自具足，能生万法——自性即最善之知识。然大珠非否定外在善知识——乃示学人：外在善知识为缘，自性善知识为因——因绿和合方能悟道。",
