    "interpretation": "赵州之\u201c汝什么处去来\u201d——你从哪里来？此为反诘之法：将问题还之学人之行履。学人问西来意，赵州反问\u201c你从哪里来\u201d——你连自己从哪里来都不清楚，还问祖师西来意？意谓：西来意不在别处，即此汝当下之行履。汝从定州来——定州亦有西来意，不须问\u201c祖师\u201d西来意。赵州以学人之行履示西来意之当下——即此当下，便是西来意。",
