    "interpretation": "黄檗之\u201c无心即是道\u201d——无心者，非无一切心——乃无妄心。妄心者，念念生灭、分别执着之心；无心者，无妄念、无分别、无执着——即此无心，便是道。道非别物——即此无心之当下。如六祖云：\u201c兀兀不修善，腾腾不造恶，寂寂断见闻，荡荡心无着。\u201d——此即无心之境界。无心非死灰——乃于一切境不执着、不分别。",
