    "interpretation": "黄檗之\u201c色即是空空即是色\u201d——此引《心经》之语以答真空妙有。真空妙有者——真空非断空，妙有非实有。色即是空——色（一切法）当体即空，非色灭后空；空即是色——空非断空，空即是色之体。真空妙有——空而不空（妙有），有而不有（真空）。悟自性者，于色中见空，于空中见色——色空不二，即真空妙有。",
