    "id": "koan-219",
    "question": "毗婆尸佛偈曰：“身从无相中受生，犹如幻出诸形像。幻人心识本来无，罪福皆空无所住。”此偈何意？",
    "answer": "身从无相中受生——身本无相，从妄想中受生，如幻化人。心识本来空寂，罪福皆不可得。此示万法缘起性空之旨。",
    "context": "毗婆尸佛传法偈。过去七佛各说一偈，明万法性空之旨。",
