    "id": "koan-220",
    "question": "释迦牟尼佛偈曰：“法本法无法，无法法亦法。今付无法时，法法何曾法。”此偈何意？",
    "answer": "法本无法——法之本性是空，故曰“法无法”。虽曰无法，此“无法”亦是法，故曰“无法法亦法”。今付此无法之法时，法法何曾有一法可得？此示传法实无所传之旨。",
    "context": "释迦牟尼佛传法偈，为七佛传法偈之最后一首，明传法实无所传。",
