    "id": "koan-221",
    "question": "《绝观论》问：“云何为心？”答：“不生不灭。”又问：“既不生不灭，何名心？”答：“以不生不灭故，名之为心。”此段何意？",
    "answer": "心本不生不灭，非从因缘生，亦非从因缘灭。以不生不灭故，名之为心。若生灭则有来去，有来去则非心。此示真心本无生灭之旨。",
    "context": "《绝观论》以问答形式直指心性，明心本不生不灭。",
    "master": "牛头法融",
    "source": "绝观论",
