    "question": "问：“云何破相？”答：“相本无相，破无所破。若执有相可破，即是被相所缚。但了相本空，即是破相。”此段何意？",
    "answer": "相本无相——万法之相从因缘生，无有自性，故曰无相。破相非灭相，而是了达相本空。若执有相可破，即被相缚。此示破相实无所破之旨。",
    "context": "《破相论》明破相之方法：了相本空，即名破相。",
