    "question": "《信心铭》曰：“至道无难，唯嫌拣择。但莫憎爱，洞然明白。”此四句何意？",
    "answer": "至道本不难，唯人自生分别——有憎有爱，有取有舍，即成障碍。但莫憎爱，不生分别，至道自然洞然明白。此为禅宗无分别心之根本纲宗。",
    "context": "三祖僧璨《信心铭》开篇四句，为禅宗纲宗。",
