    "answer": "心性本净——真心本来清净。客尘所染——烦恼如客尘，非心本有。但离妄念——去其客尘。即同如来——净心显现，与佛无二。此示禅宗“但离妄念即同如来”之旨。",
    "context": "高丽普照知讷《修心诀》明修心之要：但离妄念，即同如来。",
