    "id": "koan-234",
    "question": "大珠慧海问：“云何名顿悟？”答：“顿者，顿除妄念；悟者，悟无所得。顿除妄念名顿，悟无所得名悟。顿悟者，即顿除妄念、悟无所得也。”此段何意？",
    "answer": "顿悟非渐次修行——顿除妄念，一时放下。悟无所得——本来是佛，无所可得。此示禅宗顿悟法门之根本：但除妄念，即同如来。",
