    "answer": "又不得将迷待悟，就不可思量处思量。心无所之。如老鼠入牛角便见倒断也。",
    "context": "退隐禅师《禅家龟鉴》云：话头不得举起处承当，不得思量卜度，又不得将迷待悟，就不可思量处思量。心无所之，如老鼠入牛角便见倒断也。",
