    "question": "孤轮独照江山静",
    "answer": "孤轮独照江山静，自笑一声天地惊。",
    "context": "退隐禅师《禅家龟鉴》结尾颂曰：如斯举唱明宗旨，笑杀西来碧眼僧。然毕竟如何？孤轮独照江山静，自笑一声天地惊。",
    "interpretation": "孤轮独照——悟后心如明月，独照江山而不染一尘。自笑一声——自笑从前枉用功夫，天地惊——一悟一切悟，惊天动地。此为退隐禅师全篇总结：始于一物之名状不得，终于莫存知解，以孤轮独照之境收束全篇。",
    "master": "退隐禅师",
