    "interpretation": "“一切莫顾”是放下万缘；“安心无处”是安心于无可安之处——不是找一个清净的地方去安心，而是彻见到处都是无可安，心便无可安而自安。如人落水，到底时自然沉定，不须费力。虚明自露——不是你去明，是明自己露，只因无处可安时，妃子自现。",
