    "context": "长芦宗赣《坐禅仪》云：“坐禅本是安乐法门，但很多人因此致病，都是不善用心的缘故。若能善得其意，则自然四大轻安，精神爽利，正念分明，法味资神，寂然清乐。”此语点出坐禅之利弊两面，善用心者安乐，不善用心者反致病。",
