    "answer": "凡所有相皆是虚妄。才作佛见便被佛障，作众生见被众生障。作凡作圣作净作秽等见，尽成其障！障汝心故，总成轮转，犹如猕猴放一捉一，无有歇期。",
    "interpretation": "黄檗以猕猴放一捉一为喻，揭示一切见执皆成障碍。猕猴放一捉一，喻心识攀缘不停——放下一个执着又抓起另一个，永无止息。唯有无诸见，方能出离轮转。此与“不用求真，唯须息见”相呼应：不是要求真理，而是要止息一切见解。",
