    "id": "koan-260",
    "question": "吃茶去",
    "answer": "师问二新到：上座曾到此间否？云：不曾到。师云：吃茶去！又问那一人：曾到此间否？云：曾到。师云：吃茶去！院主问：不曾到，教伊吃茶去，即且致；曾到，为什么教伊吃茶去？师云：院主。院主应喏。师云：吃茶去！",
