    "question": "赵州勘婆子",
    "answer": "台山路有一婆子，要问僧。僧问：台山路，向什么处去？婆云：蓦直去！僧才行，婆云：又这么去也！赵州闻后，便去问：台山路，向什么处去？婆云：蓦直去！赵州才行，婆云：又这么去也！赵州便归，举似大众云：婆子今日被老僧勘破了也。",
    "context": "赵州勘破台山婆子",
