    "question": "龟毛喻何物？龟喻何物？",
    "answer": "龟喻于道，毛喻于我。故圣人无我而有道。",
    "interpretation": "法融以龟毛为喻，破除有无之见。龟有甲无毛——道真实而我本空。道非先无今有故不言有，毛非先有今无故不言无。此喻精妙：既破凡夫执我之有见，又破外道执道可求之无见，双遣有无，直指中道。",
