    "question": "道究竟属谁？",
    "answer": "究竟无所属，如空无所依。道若有系属，即有遮有开、有主有寄也。",
    "interpretation": "缘门问道属谁，入理答无所属。道若有归属，就有遮有开、有主有寄——落入二元对立。道如虚空，无所依止，无所系属，此为法界性自然之旨。此语破除\u201c道属佛\u201d\u201c道属圣\u201d之一切执着。",
