    "question": "\"道遍草木\"——草木也能成佛吗？",
    "answer": "法融说道无所不遍，草木无情本来合道。经云\"于一微尘中具含一切法\"，又云\"一切法亦如也\"——如无二无差别。草木与人在道面前平等无二。但法融并非说草木成佛，而是说道本遍一切处，草木本来在道中，不需要\"成\"佛——它们从来就在法性之中。",
    "relatedBooks": ["jueguanlun"]
