    "question": "\"起心易，灭心难；是身易，非身难\"——为什么说修道甚难？",
    "answer": "法融指出：起心容易灭心难——妄念起之即生，要彻底寂灭却极难。认同身体容易，超越身体难。有所作为容易，无所作为难。所以\"不动即真，三圣希及\"——不动不是什么都不做，而是心不妄动，这连三圣都难以达到。法融以此说明：虽然道本现成，但众生习气深重，真正做到无心绝观极为罕见。",
