    "answer": "法融并非否定念佛求佛，而是指出究竟层面：佛在心中不在心外。求酥钻水——酥在乳中不在水中，求道求佛当向心中求。法融在第四节也说\"为愚痴众生教令念佛，若有道心之士即令观身实相\"——念佛是方便门，求心是究竟门。二者不矛盾：未悟者念佛为方便，已悟者求心为究竟。",
