    "answer": "洞山问曹山名字，曹山答“本寂”。洞山问向上的，曹山答“不道”。洞山问为什么不道，曹山答“不名本寂”。深意是：名字只是假名，本寂之性岂可以名相得之？“本寂”是名，“不名本寂”是道——一语双关，既答师问，又示本体不可说之旨。这是曹洞宗师徒印心的经典对话。",
